from taf.ul.ettf.measurements.measurement import Measurement, Phycell
from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.sim.core.library import State
from taf.ul.ettf.sim.core.validator import Validator
from taf.ul.ettf.sim.simulators.egate import EgateCommand


class MeasurementActions:
    DELAY_TILL_NR_RRC_RECONF = 'DELAY_TILL_NR_RRC_RECONF'
    SEND_IMMEDIATELY = 'SEND_IMMEDIATELY'
    RESET = 'RESET'


class NoMeasurementsProvidedError(Exception):
    pass


class MeasurementSchedulingError(Exception):
    pass


class PartialMeasurementCommand(EgateCommand):
    pass


class CorrectActionTriggered(Validator):
    def __init__(self, action_type):
        self._action_type = action_type

    def validate(self, command_result):
        if "{} action is triggered".format(self._action_type) not in command_result:
            raise MeasurementSchedulingError('Expected action ({}) is not triggered'.format(self._action_type))


class MeasurementsList(list):
    def last(self):
        try:
            return self[-1]
        except IndexError:
            raise NoMeasurementsProvidedError("You must specify measurement first!")


class MeasurementsCommand(EgateCommand):
    PROMPT = "EGATE> "

    def __init__(self, ue_id, delay, periodicity):
        command = 'ue_schedule_measurement_send_nr id={} delay={} periodicity={}'.format(ue_id, delay, periodicity)
        super(MeasurementsCommand, self).__init__(command, stop_regex=self.PROMPT)
        self._measurements = MeasurementsList()

    def run(self, simulator):
        try:
            self.assemble_command_with_measurements()
            return self._run(simulator)
        finally:
            self.clear()

    def assemble_command_with_measurements(self):
        self.run_assemblers()
        self._command = Command.command_elements.default_assemble()
        self._assemble_measurements()

    def add_measurement(self, measurement):
        self._measurements.append(measurement)

    def add_phycell(self, phycell):
        self._measurements.last().add_phycell(phycell)

    def _assemble_measurements(self):
        for measurement in self._measurements:
            self._assemble_additional_object_to_command(measurement)
            for phycell in measurement.phycells():
                self._assemble_additional_object_to_command(phycell)

    def _assemble_additional_object_to_command(self, instance):
        self._command += instance.to_command()


class Measurements(State):
    def schedule_for_nr_ue(self, ue_id, delay, periodicity):
        self.start()
        self.init_command(MeasurementsCommand(ue_id, delay, periodicity))

    def measurement(self, meas_id, **meas_args):
        self.add_measurement(Measurement(meas_id, **meas_args))

    def with_physical_cell(self, phycell_id, **phycell_args):
        self.add_phycell(Phycell(phycell_id, **phycell_args))

    def delay_till_nr_rrc_reconfiguration(self):
        return self._execute_measurement_action(MeasurementActions.DELAY_TILL_NR_RRC_RECONF)

    def send_immediately(self):
        return self._execute_measurement_action(MeasurementActions.SEND_IMMEDIATELY)

    def reset(self):
        return self._execute_measurement_action(MeasurementActions.RESET)

    def _execute_measurement_action(self, action):
        self.replace_validators(CorrectActionTriggered(action))
        self.extend_base_command("action={}".format(action))
        return self.finalize()


measurements = Measurements
